css:
@font-face {
    font-family: 'DINPro';
    font-style: normal;
    font-weight: 300;
    src: local('DINPro'), url('https://fonts.cdnfonts.com/s/18774/DINPro-Light tr.woff') format('woff');
}
@font-face {
    font-family: 'DINPro';
    font-style: normal;
    font-weight: 500;
    src: local('DINPro'), url('https://fonts.cdnfonts.com/s/18774/DINPro-Medium tr.woff') format('woff');
}
@font-face {
    font-family: 'DINPro';
    font-style: normal;
    font-weight: 700;
    src: local('DINPro'), url('https://fonts.cdnfonts.com/s/18774/DINPro-Bold tr.woff') format('woff');
}
@font-face {
    font-family: 'DINPro';
    font-style: normal;
    font-weight: 900;
    src: local('DINPro'), url('https://fonts.cdnfonts.com/s/18774/DINPro-Black tr.woff') format('woff');
}

card { 
  font-size: 50%;
  font-family: 'DINPro', sans-serif;
}

.cardpenBleed {
	border:0 !important;
}

bleed {
  width:100%;
  height:100%;
  position:relative;
  background:url('../../Cards/Fallacies/Assets/Fallacy-back/Fallacy-back-bg.jpg') repeat;
  background-size:100% 100%;
  border-radius:0.125in;
  overflow:hidden;
}

.cardContent {
  position:absolute;
  top:2%;
  z-index:2;
  width:84%;
  height:95%;
  display:flex;
  flex-flow:column wrap;
  justify-content:space-between;
}

/* Vibrant red vignette effect*/
.vignetteOverlay {
  width:200%;
  height:100%;
  position:relative;
  left:-25%;
	-webkit-box-shadow:inset 3px 7px 70px 30px rgba(180, 0, 3,0.7);
    -moz-box-shadow: inset 3px 7px 70px 30px rgba(180, 0, 3,0.7);
    box-shadow: inset 3px 0px 40px 30px rgba(180, 0, 3,0.6);
}

/* Dark vignette effect*/
.vignetteOverlay2 {
  width:150%;
  height:100%;
  position:absolute;
  top:0;
  left:-25%;
  -webkit-box-shadow: inset 3px 7px 63px 4px #000);
  -moz-box-shadow: inset 3px 7px 63px 4px #000;
  box-shadow: inset 3px 0px 40px 0px rgba(0,0,0,0.8);
}

.title {
  display:flex;
  flex-flow:column;
  word-wrap:break-word;
  position:relative;
  width:90%;
  height:54%;
  max-height:3.2em;
  padding:9% 12% 0% 9%;
  font-weight:900;
  font-size:8em;
  line-height:0.85;
  fill:#fff3de;
  letter-spacing:0.03em;
  align-items:flex-start;
  z-index:3;
}

.title svg {
	margin-bottom:4%;
  	height:29%
}
.title svg text {
	letter-spacing:0.09em;
  	font-size:100px;
    color:red;
    stroke:#720000;
    stroke-width:2px;
    stroke-linecap:butt;
    stroke-linejoin:miter;
    stroke-opacity:0.3;
}

.pieces {
  	height:54%;
  	position:absolute;
  	z-index:1;
  	top:36%;
  	right:0;
  	text-align:center;
}

.pieces img {
  width:95%;
}
.footer {
	color:#fff3de;
  	text-transform:uppercase;
  	width:100%;
  	text-align:center;
  	font-family:'Bebas Neue', 'DINPro', 'Noto Sans SC', 'Vazirmatn', 'Noto Naskh Arabic', sans-serif;
  	letter-spacing:0.15em;
  	font-size:2.1em;
  	white-space:nowrap;
  	padding-bottom:0.25em;
}


/* RTL/CJK language support — #1132, chemin ACTIF.
   La version precedente s'appuyait sur trois accroches, toutes inertes : un selecteur
   d'attribut lang (aucun gabarit ne porte d'attribut lang), un selecteur de direction
   rtl (les gabarits declarent dir=auto : le navigateur CALCULE la direction, mais la
   valeur ecrite de l'attribut reste la chaine auto, qui ne matche pas), et des
   selecteurs de classe suffixes par langue — or les noms de CLASSE ne sont jamais
   traduits : ApplyFieldConversions ne remplace que le motif `<nom>}}`, donc le jeton
   {{desc_fr}}, jamais l'attribut class="desc_fr" qui n'est pas suivi de }}.
   Resultat : sur une carte ar, chaque zone tombait sur le fallback systeme, d'ou
   plusieurs polices arabes differentes sur la meme carte.
   Ici la classe .argu-lang-XX est posee dans le mustache et reecrite par
   StaticConversions (meme mecanisme que le sous-titre Memo, demontre actif).
   Portee : rien ci-dessous ne peut matcher en fr/en/ru/pt/es. */
.argu-lang-ar, .argu-lang-fa, .argu-lang-ar *, .argu-lang-fa * {
    font-family: 'Vazirmatn', 'Noto Naskh Arabic', sans-serif !important;
    /* letter-spacing dechire les liaisons des ecritures cursives : les valeurs
       livrees vont de 0.03em a 0.2em (pire cas : .header .subtitle de Memo_Back).
       Un caractere generique plutot qu'une enumeration de selecteurs : c'est
       precisement une enumeration qui avait manque Memo_Back et Virtues_Face. */
    letter-spacing: normal !important;
}
.argu-lang-zh, .argu-lang-zh * {
    font-family: 'Noto Sans SC', sans-serif !important;
}
/* #1225 - re-affirme la police de marque sur le mot-marque latin ARGUMENTUM (SVG) et la
   tagline, masques par le balayage .argu-lang-{ar,fa,zh} * ; ne touche pas aux glyphes locaux. */
.argu-lang-ar .title svg text, .argu-lang-fa .title svg text, .argu-lang-zh .title svg text {
    font-family: 'DINPro', sans-serif !important;
}
.argu-lang-ar .footer, .argu-lang-fa .footer, .argu-lang-zh .footer {
    font-family: 'Bebas Neue', 'DINPro', sans-serif !important;
}
